{
  "name": "Client Onboarding Triage",
  "nodes": [
    {
      "id": "1",
      "name": "Intake form received",
      "type": "n8n-nodes-base.webhook",
      "parameters": { "path": "onboarding-intake", "httpMethod": "POST" }
    },
    {
      "id": "2",
      "name": "Parse attachments",
      "type": "n8n-nodes-base.extractFromFile",
      "parameters": { "operation": "text", "binaryPropertyName": "attachments" }
    },
    {
      "id": "3",
      "name": "Extract client profile (Claude)",
      "type": "@n8n/n8n-nodes-langchain.anthropic",
      "parameters": {
        "model": "claude-sonnet-4-6",
        "prompt": "Extract a structured client profile from the intake text: legal_name, jurisdiction, entity_type, engagement_type, key_contacts[]. Return JSON only. If a required field is missing, set it to null — do not guess."
      }
    },
    {
      "id": "4",
      "name": "Validate required fields",
      "type": "n8n-nodes-base.if",
      "parameters": {
        "conditions": [
          { "value1": "={{$json.legal_name}}", "operation": "isNotEmpty" },
          { "value1": "={{$json.jurisdiction}}", "operation": "isNotEmpty" },
          { "value1": "={{$json.entity_type}}", "operation": "isNotEmpty" }
        ]
      }
    },
    {
      "id": "5",
      "name": "Create CRM record",
      "type": "n8n-nodes-base.httpRequest",
      "parameters": {
        "method": "POST",
        "url": "https://crm.internal.example/api/clients",
        "authentication": "predefinedCredentialType",
        "sendBody": true
      }
    },
    {
      "id": "6",
      "name": "Notify onboarding channel",
      "type": "n8n-nodes-base.slack",
      "parameters": { "channel": "#client-onboarding", "text": "={{$json.summary}}" }
    },
    {
      "id": "7",
      "name": "Exceptions: route to review",
      "type": "n8n-nodes-base.slack",
      "parameters": { "channel": "#onboarding-exceptions", "text": "Validation failed: {{$json.missing_fields}} — original documents attached." }
    },
    {
      "id": "8",
      "name": "Daily exceptions digest",
      "type": "n8n-nodes-base.scheduleTrigger",
      "parameters": { "rule": { "interval": [{ "field": "days" }] } }
    }
  ],
  "connections": {
    "Intake form received": { "main": [[{ "node": "Parse attachments" }]] },
    "Parse attachments": { "main": [[{ "node": "Extract client profile (Claude)" }]] },
    "Extract client profile (Claude)": { "main": [[{ "node": "Validate required fields" }]] },
    "Validate required fields": {
      "main": [
        [{ "node": "Create CRM record" }],
        [{ "node": "Exceptions: route to review" }]
      ]
    },
    "Create CRM record": { "main": [[{ "node": "Notify onboarding channel" }]] }
  }
}
